function validate([orders]) {
  if (!Array.isArray(orders) || orders.length < 1 || orders.length > 100000) return 'orders needs 1 to 10^5 batches.';
  for (const order of orders) {
    if (!Array.isArray(order) || order.length !== 3) return 'Each batch is [price, amount, orderType].';
    const [price, amount, type] = order;
    if (!Number.isInteger(price) || price < 1 || price > 1e9) return 'Each price is an integer from 1 to 10^9.';
    if (!Number.isInteger(amount) || amount < 1 || amount > 1e9) return 'Each amount is an integer from 1 to 10^9.';
    if (type !== 0 && type !== 1) return 'orderType is 0 (buy) or 1 (sell).';
  }
  return null;
}

