function getNumberOfBacklogOrders(orders) {
  const buys = [];
  const sells = [];
  const buyFirst = (a, b) => a[0] > b[0];
  const sellFirst = (a, b) => a[0] < b[0];
  const push = (heap, batch, before) => {
    heap.push(batch);
    let i = heap.length - 1;
    while (i > 0 && before(heap[i], heap[(i - 1) >> 1])) {
      const parent = (i - 1) >> 1;
      [heap[i], heap[parent]] = [heap[parent], heap[i]];
      i = parent;
    }
  };
  const pop = (heap, before) => {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let i = 0;
    while (true) {
      let top = i;
      for (const child of [2 * i + 1, 2 * i + 2]) {
        if (child < heap.length && before(heap[child], heap[top])) top = child;
      }
      if (top === i) return;
      [heap[i], heap[top]] = [heap[top], heap[i]];
      i = top;
    }
  };

  for (const [price, amount, type] of orders) {
    let remaining = amount;
    if (type === 0) {
      while (remaining > 0 && sells.length > 0 && sells[0][0] <= price) {
        const traded = Math.min(remaining, sells[0][1]);
        remaining -= traded;
        sells[0][1] -= traded;
        if (sells[0][1] === 0) pop(sells, sellFirst);
      }
      if (remaining > 0) push(buys, [price, remaining], buyFirst);
    } else {
      while (remaining > 0 && buys.length > 0 && buys[0][0] >= price) {
        const traded = Math.min(remaining, buys[0][1]);
        remaining -= traded;
        buys[0][1] -= traded;
        if (buys[0][1] === 0) pop(buys, buyFirst);
      }
      if (remaining > 0) push(sells, [price, remaining], sellFirst);
    }
  }

  let total = 0;
  for (const [, count] of [...buys, ...sells]) total += count;
  return total % 1000000007;
}

