function getNumberOfBacklogOrders(orders) {
  // Keep the backlog as plain lists of single prices with counts and scan for the best one each time.
  const book = { 0: new Map(), 1: new Map() };
  for (const [price, amount, type] of orders) {
    let left = amount;
    const other = book[1 - type];
    while (left > 0) {
      const prices = [...other.keys()];
      if (prices.length === 0) break;
      const best = type === 0 ? Math.min(...prices) : Math.max(...prices);
      if (type === 0 ? best > price : best < price) break;
      const take = Math.min(left, other.get(best));
      left -= take;
      if (other.get(best) === take) other.delete(best); else other.set(best, other.get(best) - take);
    }
    if (left > 0) book[type].set(price, (book[type].get(price) || 0) + left);
  }
  let sum = 0n;
  for (const side of [book[0], book[1]]) for (const count of side.values()) sum += BigInt(count);
  return Number(sum % 1000000007n);
}

