function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const spread = rand() < 0.5 ? 1000 : 1000000000;
    const orders = [];
    for (let i = 0; i < n; i++) orders.push([int(1, spread), rand() < 0.3 ? int(1, 1000000000) : int(1, 1000), int(0, 1)]);
    return [orders];
  }
  const n = int(1, 8);
  const top = int(1, 8);
  const orders = [];
  for (let i = 0; i < n; i++) {
    const amount = rand() < 0.15 ? int(999999990, 1000000000) : int(1, 6);
    orders.push([int(1, top), amount, int(0, 1)]);
  }
  return [orders];
}
